{
  "name": "CAN总线消息通知器",
  "name_en": "CAN Bus Notifier",
  "manufacturer": "",
  "description": "这不是可明确识别的物理仪器，而是一个用于 CAN 总线的消息通知与分发组件。在实验室自动化或设备集成场景中，它用于监听一个或多个 CAN 总线上的报文，并将新到达的消息分发给已注册的监听器。",
  "description_en": "This is not a clearly identifiable physical instrument, but a CAN bus message notification and dispatch component. In laboratory automation or instrument-integration workflows, it is used to monitor one or more CAN buses and distribute newly received messages to registered listeners.",
  "tag_hints": [
    "CAN bus",
    "message notification",
    "listener dispatch",
    "bus monitoring",
    "instrument integration"
  ],
  "actions": [
    {
      "action_name": "auto-bus",
      "description": "获取关联的CAN总线对象",
      "description_en": "Get the associated CAN bus object(s)."
    },
    {
      "action_name": "auto-add_bus",
      "description": "向通知器添加CAN总线",
      "description_en": "Add a CAN bus to the notifier."
    },
    {
      "action_name": "auto-stop",
      "description": "停止消息通知并停止监听器",
      "description_en": "Stop message notification and stop the listeners."
    },
    {
      "action_name": "auto-add_listener",
      "description": "添加消息监听器",
      "description_en": "Add a message listener."
    },
    {
      "action_name": "auto-remove_listener",
      "description": "移除消息监听器",
      "description_en": "Remove a message listener."
    },
    {
      "action_name": "auto-stopped",
      "description": "获取通知器是否已停止",
      "description_en": "Get whether the notifier has been stopped."
    },
    {
      "action_name": "auto-find_instances",
      "description": "查找与指定CAN总线关联的通知器实例",
      "description_en": "Find notifier instances associated with a specified CAN bus."
    }
  ]
}

